svg.script:
(() => {
  'use strict';
  const svg = document.querySelector('svg');
  const mode = svg.getAttribute('data-zoom-mode');
  const native = mode === 'native';
  const titleBase = `CnC-RA-Revive · ${native ? 'Native Scale' : 'Viewer Scale'}`;
  const mobile = navigator.maxTouchPoints > 0 &&
    (matchMedia('(pointer: coarse)').matches || /iPad|iPhone|iPod/.test(navigator.userAgent) || navigator.platform === 'MacIntel');
  const levels = [.25, .33, .5, .67, .75, .8, .9, 1, 1.1, 1.25, 1.5, 1.75, 2, 2.5, 3, 4, 5];
  const storageKey = 'cnc-ra-revive:v1.5:native-fit-dpr';
  let baseDpr = devicePixelRatio || 1;
  let zoom = 1;
  let artWidth = 0;
  let scrollbarFrame = 0;

  // The first visit establishes a fitted size at the current browser zoom.
  // Preserve that reference through reloads; never intercept native zoom input.
  if (native && !mobile) {
    try {
      const saved = Number(sessionStorage.getItem(storageKey));
      if (saved >= .1 && saved <= 20) baseDpr = saved;
      else sessionStorage.setItem(storageKey, String(baseDpr));
    } catch (_) { /* A storage-restricted browser still supports live zoom. */ }
  }

  function draw(nextZoom, anchorX = 0, anchorY = 0, preserveAnchor = true, viewport = null, scrollbarPass = false) {
    const oldWidth = artWidth;
    const pointX = scrollX + anchorX, pointY = scrollY + anchorY;
    zoom = Math.max(.25, Math.min(5, nextZoom));
    const nativeCorrection = native && !mobile ? (devicePixelRatio || 1) / baseDpr : 1;
    if (!mobile) {
      // At the height threshold, removing a scrollbar would make the full-width
      // graphic too tall again. Keep its gutter stable for that width-fit state.
      const fullWidthHeight = innerWidth * nativeCorrection * (native ? 1 : zoom) * 9 / 16;
      document.documentElement.style.overflowY = fullWidthHeight > innerHeight ? 'scroll' : 'auto';
    }
    // clientWidth rounds CSS pixels and can exceed the real viewport at
    // fractional display scaling. Undo visual magnification before sizing;
    // mobile supplies its stable layout width and never uses this measurement.
    const visual = window.visualViewport;
    const layoutWidth = viewport?.width ?? (visual
      ? visual.width * visual.scale
      : Math.max(0, document.documentElement.clientWidth - 1));
    const requestedWidth = layoutWidth * nativeCorrection * (native ? 1 : zoom);
    const displayScale = devicePixelRatio || 1;
    // Round DOWN to a physical pixel, then derive height from the same width.
    // This avoids a fractional overhang without suppressing real zoom overflow.
    artWidth = mobile ? requestedWidth : Math.floor(requestedWidth * displayScale) / displayScale;
    const artHeight = artWidth * 9 / 16;
    // Set both dimensions from one scale. No independent width/height fitting.
    svg.style.width = artWidth + 'px';
    svg.style.height = artHeight + 'px';
    svg.setAttribute('width', String(artWidth));
    svg.setAttribute('height', String(artHeight));
    // Browser zoom can update scrollbar geometry after the resize callback.
    // Recheck once on the next frame, without a recurring resize/fit loop.
    if (!mobile && !scrollbarPass) {
      cancelAnimationFrame(scrollbarFrame);
      scrollbarFrame = requestAnimationFrame(() => draw(zoom, anchorX, anchorY, preserveAnchor, null, true));
    }
    svg.setAttribute('data-viewer-zoom', String(zoom));
    // HTML uses its head title; standalone SVG uses its document-root title.
    document.title = !native && !mobile ? `${titleBase} ${Math.round(zoom * 100)}%` : titleBase;
    if (!mobile && preserveAnchor && oldWidth) {
      const ratio = artWidth / oldWidth;
      scrollTo(pointX * ratio - anchorX, pointY * ratio - anchorY);
    }
  }

  if (mobile) {
    // An unpainted SVG shape measures stable layout viewport units in both
    // standalone SVG and HTML. Do not derive layout dimensions from pinch zoom.
    const supportsSmallViewport = typeof CSS !== 'undefined' && CSS.supports('height', '100svh');
    let probe = null;
    if (supportsSmallViewport) {
      probe = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
      probe.setAttribute('data-viewport-probe', '');
      probe.style.cssText = 'width:100svw;height:100svh';
      svg.querySelector('defs').appendChild(probe);
    }
    const orientation = () => String(screen.orientation?.angle ?? window.orientation ?? screen.orientation?.type ?? 'unknown');
    const measure = () => {
      const css = probe ? getComputedStyle(probe) : null;
      return {width: css ? parseFloat(css.width) : innerWidth,
        height: css ? parseFloat(css.height) : innerHeight, orientation: orientation()};
    };
    const valid = size => Number.isFinite(size.width) && Number.isFinite(size.height) && size.width > 0 && size.height > 0;
    const same = (a, b) => a.orientation === b.orientation && Math.abs(a.width - b.width) <= 1 && Math.abs(a.height - b.height) <= 1;
    let committed = measure();
    if (!valid(committed)) committed = {width: innerWidth, height: innerHeight, orientation: orientation()};
    draw(1, 0, 0, false, committed);
    svg.setAttribute('data-touch-policy', 'browser');
    let touches = 0, gesture = false, candidate = null;
    let quietTimer = 0, deadlineTimer = 0, generation = 0, lastVisualChange = -Infinity;
    const interacting = () => touches > 0 || gesture;
    const stop = () => {
      clearTimeout(quietTimer); clearTimeout(deadlineTimer);
      quietTimer = deadlineTimer = 0; candidate = null; generation++;
    };
    const meaningful = size => size.orientation !== committed.orientation ||
      (supportsSmallViewport && Math.abs(size.width - committed.width) > 1);
    function settle() {
      if (!candidate || interacting()) { stop(); return; }
      const quietFor = performance.now() - lastVisualChange;
      if (quietFor < 150) { quietTimer = setTimeout(settle, 150 - quietFor); return; }
      const expected = candidate, ticket = generation;
      requestAnimationFrame(() => {
        if (ticket !== generation || interacting()) return;
        const first = measure();
        requestAnimationFrame(() => {
          if (ticket !== generation || interacting()) return;
          const second = measure();
          if (performance.now() - lastVisualChange < 150) { quietTimer = setTimeout(settle, 150); return; }
          if (!valid(second) || !same(first, second) || !same(expected, second)) { schedule(); return; }
          if (meaningful(second)) {
            draw(1, 0, 0, false, second);
            committed = second;
          }
          stop();
        });
      });
    }
    function schedule(visualChange = false) {
      const size = measure();
      if (!valid(size) || !meaningful(size) || interacting()) { stop(); return; }
      if (!candidate) deadlineTimer = setTimeout(stop, 800);
      if (!candidate || !same(candidate, size) || visualChange) {
        candidate = size; generation++;
        clearTimeout(quietTimer); quietTimer = setTimeout(settle, 150);
      }
    }
    addEventListener('resize', () => schedule());
    addEventListener('orientationchange', () => schedule());
    screen.orientation?.addEventListener?.('change', () => schedule());
    addEventListener('pageshow', () => schedule());
    const touchUpdate = event => {
      touches = event.touches.length;
      if (touches) stop(); else schedule();
    };
    for (const name of ['touchstart', 'touchmove', 'touchend', 'touchcancel'])
      addEventListener(name, touchUpdate, {passive: true});
    addEventListener('gesturestart', () => { gesture = true; stop(); }, {passive: true});
    addEventListener('gestureend', () => { gesture = false; schedule(); }, {passive: true});
    window.visualViewport?.addEventListener('resize', () => {
      lastVisualChange = performance.now();
      if (candidate) schedule(true);
    });
    // On touch devices BOTH file pairs use native pinch/pan. No preventDefault,
    // touch-action:none, native zoom reset, or programmatic scrolling is used.
    return;
  }

  draw(1, 0, 0, false);
  addEventListener('resize', () => draw(zoom));
  addEventListener('pageshow', () => draw(zoom));

  if (native) return;

  addEventListener('wheel', event => {
    if (!event.ctrlKey || event.altKey || !event.cancelable || !event.deltaY) return;
    event.preventDefault();
    const unit = event.deltaMode === 1 ? 16 : event.deltaMode === 2 ? innerHeight : 1;
    draw(zoom * Math.exp(-event.deltaY * unit * .002), event.clientX, event.clientY);
  }, {passive: false});

  addEventListener('keydown', event => {
    if ((!event.ctrlKey && !event.metaKey) || event.altKey || event.isComposing) return;
    if (event.target instanceof Element && event.target.closest('input,textarea,select,[contenteditable="true"]')) return;
    const plus = ['+', '=', 'Add'].includes(event.key) || event.code === 'NumpadAdd';
    const minus = ['-', '_', 'Subtract'].includes(event.key) || event.code === 'NumpadSubtract';
    const reset = event.key === '0' || event.code === 'Numpad0';
    if (!plus && !minus && !reset) return;
    event.preventDefault();
    if (reset) { draw(1, 0, 0, false); scrollTo(0, 0); }
    else draw(plus ? (levels.find(z => z > zoom + 1e-6) ?? 5) : ([...levels].reverse().find(z => z < zoom - 1e-6) ?? .25), innerWidth / 2, innerHeight / 2);
  });
})();
